arguments.content:
/* StayQuest Design System */

:root {
  --primary: #003B95;
  --primary-light: #006CE4;
  --accent: #FFB700;
  --accent-hover: #E5A500;
  --background: #ffffff;
  --foreground: #1a1a1a;
  --muted: #f5f5f5;
  --muted-foreground: #6b7280;
  --border: #e5e7eb;
  --card: #ffffff;
  --card-foreground: #1a1a1a;
  --radius: 0.5rem;
  --font-sans: "Inter", system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background: var(--background);
  color: var(--foreground);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1rem;
}

@media (min-width: 768px) {
  .container {
    padding: 0 1.5rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 2rem;
  }
}

/* Header */
.site-header {
  background: var(--primary);
  color: white;
  position: sticky;
  top: 0;
  z-index: 50;
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--accent);
}

.main-nav {
  display: none;
}

.main-nav a {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 500;
  transition: background 150ms;
}

.main-nav a:hover {
  background: rgba(255,255,255,0.1);
}

.main-nav a.active {
  background: rgba(255,255,255,0.15);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.1);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.btn-icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  color: white;
  transition: background 150ms;
}

.btn-icon:hover {
  background: rgba(255,255,255,0.1);
}

.btn-small {
  padding: 0.375rem 0.875rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 500;
  border: 1px solid rgba(255,255,255,0.3);
  color: white;
  transition: all 150ms;
}

.btn-small:hover {
  background: rgba(255,255,255,0.1);
}

.mobile-menu-btn {
  display: flex;
}

@media (min-width: 768px) {
  .main-nav {
    display: flex;
    align-items: center;
    gap: 0.25rem;
  }
  .mobile-menu-btn {
    display: none;
  }
}

/* Hero */
.hero {
  background: linear-gradient(135deg, var(--primary) 0%, #002a6d 100%);
  color: white;
  padding: 2.5rem 0 3rem;
}

.hero-title {
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0.5rem;
}

.hero-subtitle {
  font-size: 1rem;
  opacity: 0.9;
  margin-bottom: 1.5rem;
}

/* Search Box */
.search-box {
  background: var(--accent);
  border-radius: var(--radius);
  padding: 0.25rem;
}

.search-fields {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.search-field {
  background: white;
  border-radius: calc(var(--radius) - 2px);
  padding: 0.75rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.625rem;
  color: var(--foreground);
}

.search-field input,
.search-field select {
  border: none;
  outline: none;
  background: transparent;
  font-size: 0.9375rem;
  width: 100%;
  color: var(--foreground);
}

.search-field input::placeholder {
  color: var(--muted-foreground);
}

.search-btn {
  background: var(--primary-light);
  color: white;
  font-weight: 600;
  font-size: 1rem;
  padding: 0.875rem;
  border-radius: calc(var(--radius) - 2px);
  width: 100%;
  transition: background 150ms, transform 100ms;
}

.search-btn:hover {
  background: #0056b3;
}

.search-btn:active {
  transform: scale(0.98);
}

.search-options {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
  color: white;
  font-size: 0.875rem;
}

.search-options input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--primary-light);
}

@media (min-width: 768px) {
  .hero {
    padding: 3rem 0 4rem;
  }
  .hero-title {
    font-size: 2.5rem;
  }
  .search-fields {
    flex-direction: row;
  }
  .search-field {
    flex: 1;
  }
  .search-btn {
    width: auto;
    padding: 0.875rem 2rem;
  }
}

@media (min-width: 1024px) {
  .hero-title {
    font-size: 3rem;
  }
}

/* Section */
.section {
  padding: 2.5rem 0;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.375rem;
  color: var(--foreground);
}

.section-subtitle {
  font-size: 0.9375rem;
  color: var(--muted-foreground);
  margin-bottom: 1.25rem;
}

/* Trust Badges */
.trust-badges {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

.trust-badge {
  display: flex;
  align-items: flex-start;
  gap: 0.875rem;
  padding: 1rem;
  background: var(--muted);
  border-radius: var(--radius);
}

.trust-badge i {
  color: var(--primary);
  flex-shrink: 0;
  margin-top: 0.125rem;
}

.trust-badge h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 0.125rem;
}

.trust-badge p {
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

@media (min-width: 640px) {
  .trust-badges {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .trust-badges {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* Cards */
.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: box-shadow 200ms, transform 200ms;
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-img {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
}

.card-body {
  padding: 1rem;
}

.card-title {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.card-text {
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

/* Offer Cards */
.offer-card {
  background: var(--primary);
  color: white;
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.offer-card.accent {
  background: linear-gradient(135deg, #1e3a5f 0%, #0f1f3a 100%);
}

.offer-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
}

.offer-card p {
  font-size: 0.9375rem;
  opacity: 0.9;
  line-height: 1.5;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--accent);
  color: var(--foreground);
  font-weight: 600;
  font-size: 0.9375rem;
  padding: 0.625rem 1.25rem;
  border-radius: var(--radius);
  transition: background 150ms, transform 100ms;
  width: fit-content;
}

.btn-primary:hover {
  background: var(--accent-hover);
}

.btn-primary:active {
  transform: scale(0.98);
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  color: white;
  font-weight: 600;
  font-size: 0.9375rem;
  padding: 0.625rem 1.25rem;
  border-radius: var(--radius);
  border: 1px solid rgba(255,255,255,0.4);
  transition: background 150ms;
  width: fit-content;
}

.btn-outline:hover {
  background: rgba(255,255,255,0.1);
}

/* Property Types */
.property-types {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.property-type {
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  border: 1px solid var(--border);
  font-size: 0.875rem;
  color: var(--muted-foreground);
  transition: all 150ms;
  white-space: nowrap;
}

.property-type:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(0,59,149,0.04);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 0.25rem;
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
}

.tab-btn {
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--muted-foreground);
  transition: all 150ms;
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--foreground);
  background: var(--muted);
}

.tab-btn.active {
  background: var(--primary);
  color: white;
}

/* Tab Content */
.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
  animation: fadeIn 300ms ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Destination Grid */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.dest-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 4 / 3;
}

.dest-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 300ms;
}

.dest-card:hover img {
  transform: scale(1.05);
}

.dest-card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0.1) 50%, transparent 100%);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 1rem;
  color: white;
}

.dest-card-overlay h4 {
  font-size: 1rem;
  font-weight: 600;
}

.dest-card-overlay p {
  font-size: 0.875rem;
  opacity: 0.9;
}

@media (min-width: 640px) {
  .dest-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 1024px) {
  .dest-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

/* Carousel */
.carousel-wrap {
  position: relative;
}

.carousel {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: 0.5rem;
}

.carousel::-webkit-scrollbar {
  display: none;
}

.carousel-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: box-shadow 200ms;
}

.carousel-card:hover {
  box-shadow: var(--shadow-md);
}

.carousel-card img {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
}

.carousel-card-body {
  padding: 1rem;
}

.carousel-card-body h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.carousel-card-body .location {
  font-size: 0.875rem;
  color: var(--muted-foreground);
  margin-bottom: 0.5rem;
}

.rating-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

.rating-badge {
  background: var(--primary);
  color: white;
  font-size: 0.8125rem;
  font-weight: 600;
  padding: 0.125rem 0.375rem;
  border-radius: 4px;
}

.rating-text {
  font-size: 0.8125rem;
  color: var(--muted-foreground);
}

.reviews {
  font-size: 0.8125rem;
  color: var(--muted-foreground);
}

.price {
  font-size: 1rem;
  font-weight: 700;
  color: var(--foreground);
}

.price .original {
  text-decoration: line-through;
  color: var(--muted-foreground);
  font-weight: 400;
  margin-right: 0.25rem;
}

.carousel-nav {
  display: flex;
  gap: 0.5rem;
  margin-top: 1rem;
  justify-content: flex-end;
}

.carousel-nav button {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--foreground);
  transition: all 150ms;
}

.carousel-nav button:hover {
  background: var(--muted);
  border-color: var(--primary);
  color: var(--primary);
}

/* Weekend Deals */
.deals-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

.deal-card {
  display: flex;
  gap: 1rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: box-shadow 200ms;
}

.deal-card:hover {
  box-shadow: var(--shadow-md);
}

.deal-card img {
  width: 140px;
  height: 100%;
  object-fit: cover;
  flex-shrink: 0;
}

.deal-card-body {
  padding: 1rem 1rem 1rem 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.deal-card-body h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.deal-meta {
  font-size: 0.8125rem;
  color: var(--muted-foreground);
  margin-bottom: 0.5rem;
}

.deal-footer {
  margin-top: auto;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.deal-duration {
  font-size: 0.8125rem;
  color: var(--muted-foreground);
}

.deal-price .original {
  text-decoration: line-through;
  color: var(--muted-foreground);
  font-size: 0.875rem;
}

.deal-price .sale {
  font-size: 1.125rem;
  font-weight: 700;
  color: #dc2626;
}

@media (min-width: 640px) {
  .deals-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Homes */
.homes-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

@media (min-width: 640px) {
  .homes-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 1024px) {
  .homes-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

/* Loyalty CTA */
.loyalty-cta {
  background: linear-gradient(135deg, #e0f2fe 0%, #dbeafe 100%);
  border-radius: var(--radius);
  padding: 2rem;
  text-align: center;
}

.loyalty-cta h3 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
  color: var(--primary);
}

.loyalty-cta .sub {
  font-size: 1rem;
  font-weight: 600;
  color: var(--primary-light);
  margin-bottom: 0.5rem;
}

.loyalty-cta p {
  font-size: 0.9375rem;
  color: var(--muted-foreground);
  margin-bottom: 1rem;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.loyalty-buttons {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: white;
  color: var(--primary);
  font-weight: 600;
  font-size: 0.9375rem;
  padding: 0.625rem 1.5rem;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  transition: all 150ms;
}

.btn-secondary:hover {
  background: var(--muted);
}

/* Popular Links */
.popular-tabs {
  display: flex;
  gap: 0.25rem;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.popular-content a {
  display: inline-block;
  padding: 0.375rem 0;
  margin-right: 1.25rem;
  font-size: 0.9375rem;
  color: var(--primary-light);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.popular-content a:hover {
  color: var(--primary);
}

/* Footer */
.site-footer {
  background: #002a6d;
  color: white;
  padding: 2.5rem 0 1.5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.footer-col h5 {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
  opacity: 0.9;
}

.footer-col a {
  display: block;
  font-size: 0.8125rem;
  padding: 0.25rem 0;
  opacity: 0.75;
  transition: opacity 150ms;
}

.footer-col a:hover {
  opacity: 1;
  text-decoration: underline;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 1.5rem;
  text-align: center;
  font-size: 0.8125rem;
  opacity: 0.7;
}

@media (min-width: 640px) {
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

/* Package Radio */
.package-options {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.package-option {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1rem;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: white;
  font-size: 0.9375rem;
  cursor: pointer;
  transition: all 150ms;
}

.package-option:hover {
  border-color: var(--primary);
}

.package-option input {
  accent-color: var(--primary);
}

/* Logo Grid */
.logo-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  align-items: center;
  justify-content: center;
}

.logo-item {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--muted-foreground);
  opacity: 0.7;
  transition: opacity 150ms;
}

.logo-item:hover {
  opacity: 1;
  color: var(--primary);
}

/* FAQ */
.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  color: var(--foreground);
  transition: color 150ms;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-question i {
  transition: transform 200ms;
  flex-shrink: 0;
}

.faq-item.open .faq-question i {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease-out;
}

.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 1rem;
  font-size: 0.9375rem;
  color: var(--muted-foreground);
  line-height: 1.6;
}

/* Attractions */
.activity-card {
  display: flex;
  gap: 1rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  transition: box-shadow 200ms;
}

.activity-card:hover {
  box-shadow: var(--shadow-md);
}

.activity-card img {
  width: 100px;
  height: 100px;
  object-fit: cover;
  border-radius: calc(var(--radius) - 2px);
  flex-shrink: 0;
}

.activity-card-body {
  flex: 1;
}

.activity-card-body h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.activity-card-body p {
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

/* Nearby Grid */
.nearby-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.nearby-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 3 / 2;
}

.nearby-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 300ms;
}

.nearby-card:hover img {
